sys.path.insert(0,str(Path('tools').resolve()));import kb
root=Path('.').resolve();s=next(x for x in kb.sources(root) if x['source_id']=='src-000079');base=root/s['set_path'];out=base/'diagrams/business-transactions';out.mkdir(parents=True,exist_ok=True)
rec=json.loads((root/'work/documents/src-000079/records.json').read_text(encoding='utf-8'))
N='CorporateActionNotification';P='CorporateActionMovementPreliminaryAdvice';I='CorporateActionInstruction';S='CorporateActionInstructionStatusAdvice';C='CorporateActionMovementConfirmation';X='CorporateActionCancellationAdvice';R='CorporateActionInstructionCancellationRequest';RS='CorporateActionInstructionCancellationRequestStatusAdvice';PC='CorporateActionMovementPreliminaryAdviceCancellationAdvice';T='CorporateActionInstructionStatementReport';NA='CorporateActionNarrative';EP='CorporateActionEventProcessingStatusAdvice'
def step(label,direction='S->>O',note=None,side='left of S'):return {'label':label,'direction':direction,'note':note,'side':side}
