items=[
(20,207,'Announcement',ann+[step(N+' (REPL + Event stage)'),step(N+' (REPL + Eligible balance)',note='Entitlement'),step(P+' (NEWM)',note='Final entitlement (eg. Mandatory events)'),step(EP+' (Status pending)')],'P208-P216','The illustrated messages are conditional on the event and its life cycle, not all mandatory. Updated event details may cause replacements; final entitlement may be the first message for predictable events. Processing status advice may be sent when completion is delayed beyond the payment date. Source P213 contains an apparent recipient/message-name inconsistency; the drawing and adjacent P214 show Account Servicer to Account Owner.'),
(21,217,'Announcement and cancellation of event',[step(N),step(X+' (WITH)',note='Event cancellation')],'P218-P221','Trigger: the issuer withdraws a previously announced event. The Account Servicer sends withdrawal advice to the Account Owner. Withdrawal can occur at any point, after replacements, preliminary advice, or election. Issuer and intermediary chain appear in the narrative but are intentionally abstracted out of the two-role artwork.'),
(22,223,'Announcement and cancellation due to processing error',[step(N+' (NEWM)',note='Preliminary announcement'),step(X+' (PROC)',note='Cancellation due to processing error')],'P224-P227','Trigger: the Account Servicer discovers that a previous announcement to the Account Owner was erroneous, for example because the owner has no holdings in the security. The cancellation reason is processing error. Detection can follow multiple replacement notifications or preliminary advice; the two-arrow illustration is a minimal path.'),
(23,229,'Final entitlement replacement',ann+[step(P+' (NEWM)',note='Final entitlement (eg. Mandatory events)'),step(N+' (REPL)',note='Confirmed announcement with change'),step(P+' (REPL)',note='Final entitlement (eg. Mandatory events)')],'P230-P234','For a mandatory event, issuer changes affecting eligible balances or movement details after a final-entitlement advice trigger an updated confirmed notification and replacement preliminary advice. The Issuer is in the narrative but is not a third actor in the source sequence.'),
(24,238,'Election and final entitlement',elect,'P239-P241','After announcement, the Account Owner may instruct a proposed option for part or all of its eligible balance. The Account Servicer processes it and reports status; if accepted, it may send final-entitlement preliminary advice.'),
(25,243,'Election and final entitlement cancellation',elect+[step(R,'O->>S'),step(RS),step(PC),step(S+' (Default action)'),step(P+' (NEWM)',note='Final entitlement')],'P244-P250','Cancellation is conditional on the event permitting it. The request may state whether a new instruction will follow. The servicer reports cancellation status. If no new instruction arrives before its deadline and no standing instruction exists, it reports the default action and may send new final-entitlement preliminary advice. The artwork also shows cancellation of the earlier movement preliminary advice; all ten arrows are preserved.'),
(26,251,'Election and final entitlement replacement',ann+[step(I,'O->>S','Partial election','right of O'),step(S),step(P+' (NEWM)',note='Final entitlement'),step(I,'O->>S','Remaining election','right of O'),step(S),step(P+' (REPL)',note='Final entitlement')],'P252-P256','The Account Owner first instructs partially, then instructs the remaining eligible balance. After each accepted instruction the Account Servicer reports status; after the second acceptance it should send a replacement preliminary advice with updated final entitlements and movements.'),
(27,257,'Election reminder',ann+[step(N+' (RMDR)'),step(I,'O->>S'),step(S),step(P+' (NEWM)',note='Final entitlement')],'P258-P260','When the instruction deadline approaches and the Account Owner has not instructed, the Account Servicer may remind it of event details, eligible balance and options. The owner may then instruct and the election process continues.'),
(28,265,'Movement confirmation',elect+[step(C)],'P263-P269','For elective events, confirmation follows election; for non-elective events it follows announcement/final entitlement. The Account Servicer may pre-advise movements and must confirm effected cash/securities credits or debits. The drawing uses CorporateActionMovementConfirmation; P269 shortens its name to CorporateActionConfirmation.'),
(31,282,'Instruction reporting',[step(T)],'P283','The Account Servicer may report instructed, uninstructed and other balances at any time: for one or more events at a safekeeping account, or one event across one or several safekeeping accounts where the Account Owner has holdings.'),
(32,285,'Narrative exchange',[step(NA),step(NA,'O->>S')],'P286','Either functional participant may provide narrative information for taxation conditions, registration details, confirmation of holdings transfer and ancillary processes. The two directions shown do not establish a request-response dependency or mandatory ordering between otherwise independent narrative messages.')]
summary=[]
for num,hp,title,steps,range_,meaning in items:
 did=f'fig-{num:04d}';p=out/(did+'.md');fig=next(f for f in rec['figures'] if f['figure_id']==did);flow=next((base/'flows').glob(f'flow-src-000079-p{hp}-*.md'));fm,fb=kb.metadata(flow)
 code='sequenceDiagram\n    participant S as Account Servicer\n    participant O as Account Owner\n'
 for st in steps:
  if st['note']:code+='    Note '+st['side']+': '+st['note']+'\n'
  code+='    '+st['direction']+': '+st['label']+'\n'
 (out/(did+'.mmd')).write_text(code,encoding='utf-8')
 original=root/'domains/securities/assets/src-000079/originals'/f'image{num}.png'
 meta=dict(template=False,document_kind='diagram',review_status='needs-review',manual_curated=True,domain='securities',diagram_id=did,title=title,diagram_kind='sequence',content_origin='source-reconstruction',source_ids=['src-000079'],source_editions=[s['source_edition']],source_locations=[{'source_id':'src-000079','locator':' / '.join(fig['heading_path'])+'; '+fig['locator']+f'; word/media/image{num}.png; narrative {range_}'}],participants=['participant-src-000079-account-servicer','participant-src-000079-account-owner'],flow_ids=[fm['flow_id']],render_status='not-run',visual_review='not-run')
 text=kb.front(meta)+'# '+title+'\n\n## Source evidence\n\n'+kb.source_link(root,p,s)+'; '+' / '.join(fig['heading_path'])+'; '+fig['locator']+f'; word/media/image{num}.png. Narrative: {range_}.\n\n!['+title+']('+kb.rel(p,original)+')\n\n## Mermaid reconstruction\n\n```mermaid\n'+code+'```\n\n## Actors, messages and conditions\n\n'+meaning+'\n\nThe source narrative P203-P204 intentionally uses Account Servicer and Account Owner as functional roles to keep these flows generic. Intermediaries can act as servicer in one relationship and owner in another. Decorative building icons are represented by labeled participants. No additional actor or exchange is inferred from the omitted chain.\n\n'+kb.table(['Step','Sender','Receiver','Source message label','Source phase label'],[[i,'Account Owner' if x['direction'].startswith('O') else 'Account Servicer','Account Servicer' if x['direction'].startswith('O') else 'Account Owner',x['label'],x['note'] or ''] for i,x in enumerate(steps,1)])+'\n'+kb.link(p,flow,'Reusable flow and complete surrounding source narrative')+'.\n\n'+kb.link(p,root/'shared/reference/participants/participant-src-000079-account-servicer.md','Account Servicer')+'; '+kb.link(p,root/'shared/reference/participants/participant-src-000079-account-owner.md','Account Owner')+'.\n\n## Review evidence\n\nFull-size original inspected. Parse/render and rendered visual comparison pending.\n';kb.put(p,text)
 fm.update(document_kind='business-flow',manual_curated=True,participants=meta['participants']);fb=fb.replace('Purpose, trigger, preconditions and postconditions are not separately established in this extracted segment. The narrative and linked process tables preserve the available evidence.','Purpose, triggering conditions, message direction, exceptions and outcomes are curated below from the named source scenario. Formal precondition/postcondition fields are not separately provided by this scenario.');fm['limitations']=[x for x in fm.get('limitations',[]) if not x.startswith('Participants listed')]
 fb+='\n## Reviewed source sequence and conditions\n\n'+meaning+'\n\n'+kb.link(flow,p,'Source sequence reconstruction')+'.\n\n'+kb.table(['Ordered step','Initiator / sender','Receiver / responsible recipient','Message and source phase'],[[i,'Account Owner' if x['direction'].startswith('O') else 'Account Servicer','Account Servicer' if x['direction'].startswith('O') else 'Account Owner',x['label']+(' — '+x['note'] if x['note'] else '')] for i,x in enumerate(steps,1)])+'\nConditions and exceptions above come from '+range_+'. This scenario does not separately enumerate formal precondition/postcondition fields; do not infer additional guarantees. P203-P204 explains the omitted intermediary chain and interchangeable functional-role capacity.\n'
 kb.put(flow,kb.front(fm)+fb);summary.append({'diagram':p.relative_to(root).as_posix(),'source_figure':did,'steps':len(steps),'owner_to_servicer':sum(x['direction'].startswith('O') for x in steps),'flow':flow.relative_to(root).as_posix()})
